from collections import Counter


def _bands(grid, axis):
    n = len(grid) if axis == 0 else len(grid[0])
    m = len(grid[0]) if axis == 0 else len(grid)
    bands = []
    for i in range(n):
        active = any((grid[i][j] if axis == 0 else grid[j][i]) != 0 for j in range(m))
        if active:
            if bands and i == bands[-1][1] + 1:
                bands[-1][1] = i
            else:
                bands.append([i, i])
    return [tuple(b) for b in bands]


def _tile_color(grid, rb, cb):
    r0, r1 = rb
    c0, c1 = cb
    edge = [grid[r0][c] for c in range(c0, c1 + 1)]
    edge += [grid[r1][c] for c in range(c0, c1 + 1)]
    edge += [grid[r][c0] for r in range(r0 + 1, r1)]
    edge += [grid[r][c1] for r in range(r0 + 1, r1)]
    counts = Counter(x for x in edge if x != 0)
    if not counts or r1 - r0 < 2 or c1 - c0 < 2:
        return None
    frame = counts.most_common(1)[0][0]
    inside = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)
              if grid[r][c] not in (0, frame)]
    return Counter(inside).most_common(1)[0][0] if inside else None


def transform(grid):
    out = [row[:] for row in grid]
    row_bands = _bands(grid, 0)
    col_bands = _bands(grid, 1)
    colors = [[_tile_color(grid, rb, cb) for cb in col_bands] for rb in row_bands]
    counts = Counter(x for row in colors for x in row if x is not None)
    # The most frequent interior color is the background tile marker; only
    # exceptional marker colors are extended through the blank separators.
    most = max(counts.values())
    tied = {color for color, n in counts.items() if n == most}
    # In tied layouts, 2 is the repeated base marker in this tile family.
    common = 2 if 2 in tied else counts.most_common(1)[0][0]

    # Same-color exceptional centers in a common tile row connect through gaps.
    for i, (r0, r1) in enumerate(row_bands):
        for color in set(x for x in colors[i] if x is not None and x != common):
            hits = [j for j, x in enumerate(colors[i]) if x == color]
            for a, b in zip(hits, hits[1:]):
                for j in range(a, b):
                    lo, hi = col_bands[j][1] + 1, col_bands[j + 1][0]
                    for r in range(r0 + 1, r1):
                        for c in range(lo, hi):
                            out[r][c] = color

    # Same-color tile centers in a common tile column connect through separator gaps.
    for j, (c0, c1) in enumerate(col_bands):
        col = [row[j] if j < len(row) else None for row in colors]
        for color in set(x for x in col if x is not None and x != common):
            hits = [i for i, x in enumerate(col) if x == color]
            for a, b in zip(hits, hits[1:]):
                for k in range(a, b):
                    lo, hi = row_bands[k][1] + 1, row_bands[k + 1][0]
                    for r in range(lo, hi):
                        for c in range(c0 + 1, c1):
                            out[r][c] = color
    return out

